pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 value, bytes memory data) public {
        vm.assume(sender != address(0) && sender != c.owner());
        vm.assume(value <= 100 ether);

        uint256 depositsBefore = c.depositsCount();

        // Call sendMoney via prank as a non-owner to ensure it reverts and doesn't change state
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", sender, value, data));

        uint256 depositsAfter = c.depositsCount();

        // General rule: depositsCount should not increase when called by non-owner (revert prevents any effect)
        assertTrue(depositsAfter == depositsBefore);
    }
}

