pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 amount, bytes memory data) public {
        vm.assume(sender != address(0));
        vm.assume(amount <= address(c).balance); // ensure enough balance

        uint256 beforeDeposits = c.depositsCount();
        (bool success, ) = address(c).call{value: amount}(data);

        // Record if a receive() would have been triggered
        bool triggeredReceive = (amount > 0 && data.length == 0); // receive() is called when data is empty and value > 0

        // Now call sendMoney as owner to observe any side effects
        vm.prank(c.owner());
        (bool sendSuccess, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", sender, 0, ""));

        uint256 afterDeposits = c.depositsCount();

        // The invariant: if receive() was triggered, depositsCount should increase by 1; otherwise unchanged
        if (triggeredReceive && success) {
            assertTrue(afterDeposits == beforeDeposits + 1, "depositsCount should increment on receive");
        } else {
            assertTrue(afterDeposits == beforeDeposits, "depositsCount should not change without receive");
        }
    }
}

