pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount, bytes memory data) public {
        vm.assume(amount > 0 && amount <= 1 ether);
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();
        vm.prank(c.owner());
        c.sendMoney(sender, amount, data);
        uint256 balanceAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount();
        // If the call succeeded and transferred value, depositsCount should increment
        // The effect of sendMoney on balance is: balanceAfter = balanceBefore - amount + (value sent to c via receive?)
        // Actually sendMoney sends ether to 'sender' via call, which may trigger receive on sender if it's a contract
        // But we can observe depositsCount change only if the call failed or sent to EOA; for simplicity, we check a general invariant
        // The intended general rule: depositsCount never decreases and only changes when receive is triggered
        assertTrue(depositsAfter >= depositsBefore);
    }
}

