        uint256 depositsBeforeSend = c.depositsCount();

        // Now call sendMoney
        vm.prank(c.owner());
        c.sendMoney(sender, value, data);

        uint256 depositsAfterSend = c.depositsCount();

        // Rule: depositsCount should be >= the number of receive calls made before this sendMoney
        assertTrue(depositsAfterSend >= numReceive);
    }
}

