pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 value, bytes memory data, uint256 receiveCount) public {
        // Bound receiveCount to a reasonable number
        receiveCount = bound(receiveCount, 0, 10);
        // Ensure sender is not the zero address (for prank)
        vm.assume(sender != address(0));

        // Simulate receive calls by sending ether to the contract
        for (uint256 i = 0; i < receiveCount; i++) {
            vm.deal(address(c), 1 ether);  // Give contract some ether for transfer
            (bool success, ) = address(c).call{value: 1 wei}("");
            require(success, "receive failed");
        }

        // Record depositsCount after receive calls
        uint256 countAfterReceive = c.depositsCount();

        // Now call sendMoney as owner (the deployer is owner by default)
        // We need to send some ether to contract first to avoid revert due to insufficient balance
        vm.deal(address(c), 1 ether);
        c.sendMoney(sender, 0, data);

        // After sendMoney, depositsCount should remain unchanged (equal to countAfterReceive)
        // because sendMoney does not modify depositsCount in reference C
        assertTrue(c.depositsCount() == countAfterReceive);
    }
}

