pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(c));
        uint256 ownerBefore = address(this).balance;
        uint256 transferAmount = bound(value, 0, address(this).balance);
        (bool sent, ) = address(c).call{value: transferAmount}("");
        require(sent, "deposit failed");
        uint256 cBalanceBefore = address(c).balance;

        // Try sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, transferAmount, data));

        uint256 ownerAfter = address(this).balance;
        uint256 cBalanceAfter = address(c).balance;

        // If sendMoney succeeded, owner balance should decrease by transferAmount
        // and contract balance should decrease by transferAmount
        if (success) {
            assertTrue(ownerBefore - ownerAfter == transferAmount && cBalanceBefore - cBalanceAfter == transferAmount);
        } else {
            // If reverted, owner balance unchanged
            assertTrue(ownerBefore == ownerAfter && cBalanceBefore == cBalanceAfter);
        }
    }
}

